def solve_langford(n, fixed):
    seq = [0] * (2 * n)
    for pos, val in fixed.items():
        seq[pos] = val

    used = [False] * (n + 1)
    for pos, val in fixed.items():
        used[val] = True

    def backtrack(idx):
        if idx == 2 * n:
            return True

        if seq[idx] != 0:
            return backtrack(idx + 1)

        for v in range(1, n + 1):
            if not used[v]:
                # Try placing v at idx and idx + v + 1
                if idx + v + 1 < 2 * n and seq[idx + v + 1] == 0:
                    seq[idx] = v
                    seq[idx + v + 1] = v
                    used[v] = True
                    if backtrack(idx + 1):
                        return True
                    seq[idx] = 0
                    seq[idx + v + 1] = 0
                    used[v] = False
        return False

    if backtrack(0):
        return seq
    else:
        return None

