def solve_langford_flexible(n, fixed):
    seq = [0] * (2 * n)
    # fixed is a dictionary of {index: value}
    # We need to ensure that for each value v, if it's fixed at one position,
    # the other position is either fixed or can be determined.

    # Let's store the fixed positions for each value
    val_positions = {}
    for pos, val in fixed.items():
        if val not in val_positions:
            val_positions[val] = []
        val_positions[val].append(pos)
        seq[pos] = val

    # Check if any value has more than 2 positions fixed
    for val, positions in val_positions.items():
        if len(positions) > 2:
            return None
        if len(positions) == 2:
            # Check if the distance is correct
            if abs(positions[0] - positions[1]) != val + 1:
                return None

    used = [False] * (n + 1)
    for val in val_positions:
        used[val] = True

    def backtrack(idx):
        if idx == 2 * n:
            return True

        if seq[idx] != 0:
            return backtrack(idx + 1)

        for v in range(1, n + 1):
            if not used[v]:
                # Try placing v at idx and idx + v + 1
                if idx + v + 1 < 2 * n and seq[idx + v + 1] == 0:
                    seq[idx] = v
                    seq[idx + v + 1] = v
                    used[v] = True
                    if backtrack(idx + 1):
                        return True
                    seq[idx] = 0
                    seq[idx + v + 1] = 0
                    used[v] = False
                # Try placing v at idx and idx - (v + 1)
                elif idx - (v + 1) >= 0 and seq[idx - (v + 1)] == 0:
                    # This case is actually covered by the first one if we iterate through all positions
                    # But let's be careful.
                    pass
        return False

    if backtrack(0):
        return seq
    else:
        return None

